import { LOW_DATA_THRESHOLD } from "./customer-insights";

export const COMPACT_OPPORTUNITY_COUNT_CHARACTERS = 5;

export function hasEstablishedDashboardSignal(reviewOpportunities: number): boolean {
  return Number.isFinite(reviewOpportunities) && reviewOpportunities >= LOW_DATA_THRESHOLD;
}

